const now = new Date();
const nowIso = now.toLocaleString('sv-SE', { timeZone: 'Asia/Ho_Chi_Minh' }).replace(' ', 'T') + '+07:00';
const tag = now.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', timeZone: 'Asia/Ho_Chi_Minh' });
const replyOutput = (() => {
  const raw = $('Summarize Reply').item.json.output;
  if (typeof raw === 'object' && raw !== null) return raw;
  if (typeof raw === 'string') { try { return JSON.parse(raw); } catch(e) {} }
  return {};
})();
const summary = replyOutput.summary || '';
const status  = replyOutput.status  || 'in_progress';
const reason  = replyOutput.reason  || '';
const newLine    = '[' + tag + '] ' + summary;
const statusLine = 'Status \u2192 ' + status + ': ' + reason;
return [{ json: {
  latest_note: (newLine + ' | ' + statusLine).slice(0, 500),
  latest_note_at: nowIso,
  last_updated:  nowIso,
  status:  status,
  summary: summary,
  reason:  reason
}}];

