const out  = $('Generate WIP Fields').item.json.output || {};
const open = $('Build Open Task Index').item.json.open_tasks || [];

const isSame = out.match_decision === 'same_task';
const conf   = typeof out.confidence === 'number' ? out.confidence : 0;

let matched_wip_task_id = '';
if (isSame && out.match_idx != null) {
  const hit = open.find(t => t.idx === out.match_idx);
  if (hit) matched_wip_task_id = hit.wip_task_id;
}

// Score only trusted when decision=same_task AND a real id was resolved
let match_band = 'reject';
if (isSame && matched_wip_task_id) {
  if (conf > 0.7)       match_band = 'safe';
  else if (conf >= 0.5) match_band = 'review';
}

return [{ json: {
  match_band,
  matched_wip_task_id,
  match_confidence: conf,
  match_reason: out.match_reason || '',
  output: out
} }];

