// Aggregate open wip_tasks into a single item with idx → wip_task_id map,
// attach recent notes (≤5 per task) for richer semantic matching context.
const taskRows = ($('Load Open WIP Tasks').all() || [])
  .map(i => i.json).filter(r => r && r.id);

const toMs = (v) => {
  if (!v) return 0;
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : 0;
};

taskRows.sort((a, b) =>
  toMs(b.last_updated || b.latest_note_at || b.updated_at) -
  toMs(a.last_updated || a.latest_note_at || a.updated_at)
);
const capped = taskRows.slice(0, 40);

// httpRequest splits the array response into one item per row, so use .all().
// PostgREST returned newest-first; keep first 5 per task.
const noteItems = $('Load Open WIP Notes').all() || [];
const byTask = new Map();
for (const it of noteItems) {
  const n = it && it.json;
  if (!n || !n.wip_task_id) continue;
  const list = byTask.get(n.wip_task_id) || [];
  if (list.length >= 5) continue;
  list.push({
    content: String(n.content || '').replace(/\s+/g, ' ').trim().slice(0, 240),
    created_at: n.created_at || ''
  });
  byTask.set(n.wip_task_id, list);
}

const open_tasks = capped.map((r, i) => ({
  idx: i + 1,
  wip_task_id: r.id,
  project_client: r.project_client || 'Internal',
  task: r.task || '',
  latest_note: r.latest_note || '',
  recent_notes: byTask.get(r.id) || []
}));

return [{ json: { open_tasks } }];

